{% extends "insurance/base.html" %}
{% block content %}
<h1>Филиалы</h1>
<p><a href="{% url 'insurance:branch-create' %}">Добавить</a></p>
<table border="1" cellpadding="6">
  <tr><th>Название</th><th>Город</th><th>Телефон</th><th></th></tr>
  {% for b in branches %}
  <tr>
    <td><a href="{% url 'insurance:branch-detail' b.pk %}">{{ b.name }}</a></td>
    <td>{{ b.city }}</td>
    <td>{{ b.phone }}</td>
    <td>
      <a href="{% url 'insurance:branch-update' b.pk %}">Изменить</a>
      <a href="{% url 'insurance:branch-delete' b.pk %}">Удалить</a>
    </td>
  </tr>
  {% empty %}
  <tr><td colspan="4">Нет записей.</td></tr>
  {% endfor %}
</table>
{% include "insurance/_pagination.html" %}
{% endblock %}

