{% extends "insurance/base.html" %}
{% block content %}
<h1>Главная</h1>
{% if latest_news %}
  <section>
    <h2>Последняя опубликованная новость</h2>
    <p><strong>{{ latest_news.title }}</strong> <small>({{ latest_news.published_at|date:"d.m.Y" }})</small></p>
    <p>{{ latest_news.summary }}</p>
    {% if latest_news.image_url %}
      <p><img src="{{ latest_news.image_url }}" alt="" width="400" height="200" loading="lazy"></p>
    {% endif %}
    <p><a href="{% url 'insurance:news-detail' latest_news.slug %}">Читать далее</a></p>
  </section>
{% else %}
  <p>Новостей пока нет — добавьте через админку или <code>seed_data</code>.</p>
{% endif %}
{% endblock %}

{% extends "insurance/base.html" %}
{% block title %}О компании{% endblock %}
{% block content %}
<h1>О компании</h1>
{% if company %}
  <div>{{ company.about_text|linebreaks }}</div>
  <h2>Реквизиты</h2>
  <table border="1" cellpadding="8">
    <tr><th>Поле</th><th>Значение</th></tr>
    {% for row in company.requisites.all %}
      <tr><td>{{ row.label }}</td><td>{{ row.value }}</td></tr>
    {% empty %}
      <tr><td colspan="2">Реквизиты не заполнены.</td></tr>
    {% endfor %}
  </table>
{% else %}
  <p>Данные «О компании» не созданы. Добавьте <code>CompanyProfile</code> в админке.</p>
{% endif %}
{% endblock %}

{% extends "insurance/base.html" %}
{% block title %}Новости{% endblock %}
{% block content %}
<h1>Новости</h1>
{% for a in articles %}
  <article style="margin-bottom:1.5rem;border-bottom:1px solid #ccc;padding-bottom:1rem;">
    <h2><a href="{% url 'insurance:news-detail' a.slug %}">{{ a.title }}</a></h2>
    <p>{{ a.summary }}</p>
    {% if a.image_url %}
      <p><img src="{{ a.image_url }}" alt="" width="320" height="160" loading="lazy"></p>
    {% endif %}
    <p><a href="{% url 'insurance:news-detail' a.slug %}">Читать далее</a></p>
  </article>
{% empty %}
  <p>Нет опубликованных новостей.</p>
{% endfor %}
{% include "insurance/_pagination.html" %}
{% endblock %}

{% extends "insurance/base.html" %}
{% block title %}{{ article.title }}{% endblock %}
{% block content %}
<article>
  <h1>{{ article.title }}</h1>
  <p><small>Опубликовано: {{ article.published_at|date:"d.m.Y H:i" }}</small></p>
