from django.contrib.auth.mixins import UserPassesTestMixin
from django.urls import reverse_lazy


class EmployeeOrSuperuserMixin(UserPassesTestMixin):
    """CRM access: employees group or Django superuser."""

    login_url = reverse_lazy("login")

    def test_func(self):
        u = self.request.user
        if not u.is_authenticated:
            return False
        if u.is_superuser:
            return True
        return u.groups.filter(name="employee").exists()


class ClientGroupMixin(UserPassesTestMixin):
    """Registered client (lab group name: client)."""

    login_url = reverse_lazy("login")

    def test_func(self):
        u = self.request.user
        return u.is_authenticated and u.groups.filter(name="client").exists()

def access_flags(request):
    u = request.user
    staff = (
        u.is_active
        and u.is_authenticated
        and (u.is_superuser or u.groups.filter(name="employee").exists())
    )
    client = u.is_active and u.is_authenticated and u.groups.filter(name="client").exists()
    return {
        "show_crm_tools": staff,
        "is_client_group": client,
    }

