<script>
(function() {
  const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
  document.getElementById('tz-label').textContent = tz;
  const d = new Date();
  const pad = n => String(n).padStart(2, '0');
  document.getElementById('local-now').textContent =
    pad(d.getDate()) + '/' + pad(d.getMonth() + 1) + '/' + d.getFullYear() + ' ' +
    pad(d.getHours()) + ':' + pad(d.getMinutes());

  const url = "{% url 'insurance:stats-charts-json' %}";
  fetch(url, { credentials: 'same-origin' })
    .then(r => r.json())
    .then(data => {
      const opts = { responsive: true, maintainAspectRatio: true };
      new Chart(document.getElementById('chartContracts'), {
        type: 'bar',
        data: {
          labels: data.contracts_by_type.labels,
          datasets: [{ label: 'Договоров по видам', data: data.contracts_by_type.data }]
        },
        options: { ...opts, plugins: { title: { display: true, text: 'Распределение договоров' } } }
      });
      new Chart(document.getElementById('chartPremiumsType'), {
        type: 'bar',
        data: {
          labels: data.premiums_by_type.labels,
          datasets: [{ label: 'Сумма премий', data: data.premiums_by_type.data }]
        },
        options: { ...opts, plugins: { title: { display: true, text: 'Премии по видам' } } }
      });
      new Chart(document.getElementById('chartPremiumsMonth'), {
        type: 'line',
        data: {
          labels: data.premiums_by_month.labels,
          datasets: [{ label: 'Премии по месяцам', data: data.premiums_by_month.data, tension: 0.2 }]
        },
        options: { ...opts, plugins: { title: { display: true, text: 'Динамика премий' } } }
      });
    })
    .catch(() => {});
})();
</script>
