/**
 * Поиск и сортировка таблиц на стороне фронта (без перезагрузки страницы).
 */
(function () {
  function initTable(table) {
    const tbody = table.querySelector("tbody");
    if (!tbody) return;
    const rows = Array.from(tbody.querySelectorAll("tr"));
    const toolbar = document.createElement("div");
    toolbar.className = "table-toolbar";
    toolbar.style.marginBottom = "0.5rem";
    toolbar.innerHTML =
      '<label>Поиск: <input type="search" class="js-table-search" placeholder="фильтр по тексту…"></label> ' +
      '<label>Сортировка: <select class="js-table-sort">' +
      '<option value="">—</option>' +
      '<option value="0-asc">Колонка 1 ↑</option>' +
      '<option value="0-desc">Колонка 1 ↓</option>' +
      '<option value="1-asc">Колонка 2 ↑</option>' +
      '<option value="1-desc">Колонка 2 ↓</option>' +
      '<option value="2-asc">Колонка 3 ↑</option>' +
      '<option value="2-desc">Колонка 3 ↓</option>' +
      "</select></label>";
    table.parentNode.insertBefore(toolbar, table);

    const searchInput = toolbar.querySelector(".js-table-search");
    const sortSelect = toolbar.querySelector(".js-table-sort");

    function cellText(row, col) {
      const cell = row.cells[col];
      if (!cell) return "";
      return (cell.dataset.sort || cell.textContent || "").trim().toLowerCase();
    }

    function apply() {
      const q = (searchInput.value || "").trim().toLowerCase();
      let visible = rows.filter((row) => {
        if (!q) return true;
        return row.textContent.toLowerCase().includes(q);
      });
      const sortVal = sortSelect.value;
      if (sortVal) {
        const [col, dir] = sortVal.split("-");
        const c = parseInt(col, 10);
        visible.sort((a, b) => {
          const av = cellText(a, c);
          const bv = cellText(b, c);
          if (av < bv) return dir === "asc" ? -1 : 1;
          if (av > bv) return dir === "asc" ? 1 : -1;
          return 0;
        });
      }
      tbody.innerHTML = "";
      visible.forEach((r) => tbody.appendChild(r));
      rows.forEach((r) => {
        if (!visible.includes(r)) tbody.appendChild(r);
      });
    }

    searchInput.addEventListener("input", apply);
    sortSelect.addEventListener("change", apply);
  }

  document.addEventListener("DOMContentLoaded", function () {
    document.querySelectorAll("table.js-filter-table").forEach(initTable);
  });
})();

